const s = $getWorkflowStaticData('global');
let b = $input.first().json.body;
if (typeof b === 'string') b = JSON.parse(b.replace(/\bNaN\b/g, 'null'));
s.list = (b && b.list) || [];
s.updated = new Date().toISOString();
return [{ json: { ok: true, count: s.list.length } }];

const s = $getWorkflowStaticData('global');
const list = (s.list || []).slice();
const col = x => /ABOVE/.test(x) ? '#16a34a' : /BELOW/.test(x) ? '#dc2626' : '#6b7280';
const f = v => (v === null || v === undefined || Number.isNaN(v)) ? '-' : v;
// crossed tickers first (PDH/PDL, then PMH/PML), INSIDE last
const rank = x => /PDH|PDL/.test(x) ? 0 : /PMH|PML/.test(x) ? 1 : 2;
list.sort((a, b) => rank(a.signal) - rank(b.signal));
const et = s.updated ? new Date(s.updated).toLocaleString('en-US', { timeZone: 'America/New_York' }) + ' ET' : 'no data yet';
const rows = list.map(r => `<tr><td><b>${r.t}</b></td><td>${f(r.price)}</td><td style="background:${col(r.signal)};color:#fff">${r.signal}</td><td style="background:${col(r.side)};color:#fff">${r.side}</td><td>${f(r.pmh)}</td><td>${f(r.pml)}</td><td>${f(r.pdh)}</td><td>${f(r.pdl)}</td><td>${f(r.vwap)}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><meta http-equiv=refresh content=60><title>CC Levels</title><style>body{font-family:sans-serif;background:#0f172a;color:#e2e8f0;padding:6px;font-size:11px;margin:0}h2{font-size:13px;margin:2px 0}p{margin:2px 0 4px;font-size:10px}table{border-collapse:collapse;width:100%}td,th{padding:2px 4px;border-bottom:1px solid #334155;text-align:center;white-space:nowrap}th{color:#94a3b8;font-weight:600}.w{overflow-x:auto}</style></head><body><h2>Key Levels <span style="font-size:10px;color:#94a3b8">levels v3</span></h2><p>Updated: ${et} (page refreshes every 60s)</p><div class=w><table><tr><th>Ticker</th><th>Price</th><th>Level</th><th>VWAP</th><th>PMH</th><th>PML</th><th>PDH</th><th>PDL</th><th>VWAP</th></tr>${rows || '<tr><td colspan=9>No data yet</td></tr>'}</table></div></body></html>`;
return [{ json: { html } }];
